def transform(grid):
    """Transform 30x30 grid to 10x10 by taking min of each 3x3 block."""
    result = [[0]*10 for _ in range(10)]
    for r in range(10):
        for c in range(10):
            row_start = r*3
            col_start = c*3
            block = [grid[row_start+dr][col_start+dc] for dr in range(3) for dc in range(3)]
            result[r][c] = min(block)
    return result

